       text-rendering: optimizeLegibility;
     }

     img {
       max-width: 100%;
       display: block;
     }

     a {
       color: var(--color-link);
       text-decoration-thickness: 0.12em;
       text-underline-offset: 0.18em;
     }

     a:hover {
       text-decoration-thickness: 0.16em;
     }

     :focus-visible {
       outline: 0.2rem solid var(--color-focus);
       outline-offset: 0.2rem;
     }

     .skip-link {
       position: absolute;
       left: 1rem;
       top: 1rem;
       z-index: 20;
       padding: 0.75rem 1rem;
       border-radius: 999px;
       background: var(--color-surface);
       box-shadow: var(--shadow);
       transform: translateY(-180%);
       transition: transform 0.2s ease;
     }

     .skip-link:focus,
     .skip-link:focus-visible {
       transform: translateY(0);
     }

     .page-shell {
       width: min(100% - 2rem, var(--content-width));
       margin: 0 auto;
     }

     .site-header {
       padding: 1rem 0 0;
     }

     .header-bar {
       display: flex;
       align-items: center;
       justify-content: space-between;
       gap: 1rem;
       padding: 1rem 1.25rem;
       border: 1px solid var(--color-border);
       border-radius: 999px;
       background: rgba(255, 255, 255, 0.76);
       backdrop-filter: blur(14px);
       box-shadow: 0 10px 28px rgba(48, 33, 18, 0.06);
     }

     .brand {
       display: inline-flex;
       align-items: center;
       gap: 0.75rem;
       min-width: 0;
       text-decoration: none;
       color: inherit;
       font-weight: 700;
       letter-spacing: 0.02em;
     }

     .brand-mark {
       display: grid;
       place-items: center;
       width: 2.4rem;
       height: 2.4rem;
       border-radius: 50%;
       background: linear-gradient(135deg, #3f2b1c, #a97145);
       color: #fff;
       flex: none;
     }

     .brand span {
       overflow: hidden;
       text-overflow: ellipsis;
       white-space: nowrap;
     }

     .site-nav ul {
       display: flex;
       flex-wrap: wrap;
       gap: 0.75rem;
       padding: 0;
       margin: 0;
       list-style: none;
     }

     .site-nav a {
       display: inline-flex;
       align-items: center;
       padding: 0.7rem 0.95rem;
       border-radius: 999px;
       color: var(--color-text);
       text-decoration: none;
       border: 1px solid transparent;
     }

     .site-nav a:hover,
     .site-nav a:focus-visible {
       background: var(--color-surface);
       border-color: var(--color-border);
     }

     .hero {
       display: grid;
       grid-template-columns: 1.15fr 0.85fr;
       gap: 1.5rem;
       align-items: stretch;
       padding: 1.5rem 0 0;
     }

     .hero-copy,
     .hero-panel,
     .section-card {
       background: var(--color-surface);
       border: 1px solid var(--color-border);
       border-radius: var(--radius-xl);
       box-shadow: var(--shadow);
     }

     .hero-copy {
       padding: clamp(1.5rem, 2vw, 2.5rem);
       display: grid;
       gap: 1.25rem;
       align-content: center;
     }

     .eyebrow {
       margin: 0;
       text-transform: uppercase;
       letter-spacing: 0.12em;
       font-size: 0.78rem;
       color: var(--color-muted-text);
       font-weight: 700;
     }

     h1 {
       margin: 0;
       font-size: clamp(2.4rem, 4vw, 4.9rem);
       line-height: 0.96;
       letter-spacing: -0.05em;
       max-width: 12ch;
     }

     .hero-copy p {
       margin: 0;
       max-width: 60ch;
       color: var(--color-muted-text);
       font-size: 1.05rem;
     }

     .hero-actions {
       display: flex;
       flex-wrap: wrap;
       gap: 0.75rem;
     }

     .button {
       display: inline-flex;
       align-items: center;
       justify-content: center;
       gap: 0.5rem;
       min-height: 2.875rem;
       padding: 0.8rem 1.15rem;
       border-radius: 999px;
       border: 1px solid transparent;
       background: var(--color-text);
       color: #fff;
       font: inherit;
       font-weight: 600;
       text-decoration: none;
       cursor: pointer;
     }

     .button:hover {
       filter: brightness(1.06);
     }

     .button.secondary {
       background: transparent;
       color: var(--color-text);
       border-color: var(--color-border);
     }

     .hero-meta {
       display: flex;
       flex-wrap: wrap;
       gap: 1rem;
       margin: 0;
     }

     .hero-meta div {
       display: grid;
       gap: 0.25rem;
       min-width: 8rem;
     }

     .hero-meta dt {
       font-size: 0.82rem;
       color: var(--color-muted-text);
     }

     .hero-meta dd {
       margin: 0;
       font-weight: 700;
     }
