      align-items: center;
      gap: 0.75rem;
      min-width: 0;
      text-decoration: none;
      color: inherit;
      font-weight: 700;
      letter-spacing: 0.02em;
    }

    .brand-mark {
      display: grid;
      place-items: center;
      width: 2.4rem;
      height: 2.4rem;
      border-radius: 50%;
      background: linear-gradient(135deg, #3f2b1c, #a97145);
      color: #fff;
      flex: none;
    }

    .brand span {
      overflow: hidden;
      text-overflow: ellipsis;
      white-space: nowrap;
    }

    .site-nav ul {
      display: flex;
      flex-wrap: wrap;
      gap: 0.75rem;
      padding: 0;
      margin: 0;
      list-style: none;
    }

    .site-nav a {
      display: inline-flex;
      align-items: center;
      padding: 0.7rem 0.95rem;
      border-radius: 999px;
      color: var(--color-text);
      text-decoration: none;
      border: 1px solid transparent;
    }

    .site-nav a:hover,
    .site-nav a:focus-visible {
      background: var(--color-surface);
      border-color: var(--color-border);
    }

    .hero {
      display: grid;
      grid-template-columns: 1.15fr 0.85fr;
      gap: 1.5rem;
      align-items: stretch;
      padding: 1.5rem 0 0;
    }

    .hero-copy,
    .hero-panel,
    .section-card {
      background: var(--color-surface);
      border: 1px solid var(--color-border);
      border-radius: var(--radius-xl);
      box-shadow: var(--shadow);
    }

    .hero-copy {
      padding: clamp(1.5rem, 2vw, 2.5rem);
      display: grid;
      gap: 1.25rem;
      align-content: center;
    }

    .eyebrow {
      margin: 0;
      text-transform: uppercase;
      letter-spacing: 0.12em;
      font-size: 0.78rem;
      color: var(--color-muted-text);
      font-weight: 700;
    }

    h1 {
      margin: 0;
      font-size: clamp(2.4rem, 4vw, 4.9rem);
      line-height: 0.96;
      letter-spacing: -0.05em;
      max-width: 12ch;
    }

    .hero-copy p {
      margin: 0;
      max-width: 60ch;
      color: var(--color-muted-text);
      font-size: 1.05rem;
    }

    .hero-actions {
      display: flex;
      flex-wrap: wrap;
      gap: 0.75rem;
    }

    .button {
      display: inline-flex;
      align-items: center;
      justify-content: center;
      gap: 0.5rem;
      min-height: 2.875rem;
      padding: 0.8rem 1.15rem;
      border-radius: 999px;
      border: 1px solid transparent;
      background: var(--color-text);
      color: #fff;
      font: inherit;
      font-weight: 600;
      text-decoration: none;
      cursor: pointer;
    }

    .button:hover {
      filter: brightness(1.06);
    }

    .button.secondary {
      background: transparent;
      color: var(--color-text);
      border-color: var(--color-border);
    }

    .hero-meta {
      display: flex;
      flex-wrap: wrap;
      gap: 1rem;
      margin: 0;
    }

    .hero-meta div {
      display: grid;
      gap: 0.25rem;
      min-width: 8rem;
    }

    .hero-meta dt {
      font-size: 0.82rem;
      color: var(--color-muted-text);
    }

    .hero-meta dd {
      margin: 0;
      font-weight: 700;
    }

    .hero-panel {
      padding: 1.25rem;
      display: grid;
      gap: 1rem;
      align-content: space-between;
      background:
        linear-gradient(180deg, rgba(255, 255, 255, 0.94), rgba(255, 255, 255, 0.88)),
        radial-gradient(circle at top, #f1dfcc 0, transparent 48%);
    }

    .feature-spot {
      display: grid;
      gap: 1rem;
      padding: 1rem;
      border-radius: var(--radius-lg);
      background: var(--color-surface-alt);
    }

    .feature-visual {
      border-radius: 1.5rem;
      min-height: 18rem;
      padding: 1.25rem;
      display: grid;
      align-content: end;
      background:
        linear-gradient(160deg, rgba(0, 0, 0, 0.02), transparent 36%),
        linear-gradient(135deg, #efc8a6 0%, #d9a06b 55%, #69412a 100%);
      color: #fff;
      position: relative;
      overflow: hidden;
    }

    .feature-visual::before {
      content: "";
      position: absolute;
      inset: 1rem 1rem auto auto;
      width: 6rem;
      height: 6rem;
      border-radius: 50%;
      border: 1px solid rgba(255, 255, 255, 0.35);
    }

    .feature-visual strong {
      font-size: 1.1rem;
    }

    .feature-visual p {
      margin: 0.25rem 0 0;
      max-width: 18ch;
      color: rgba(255, 255, 255, 0.88);
    }

    .badge-row {
      display: flex;
      flex-wrap: wrap;
      gap: 0.5rem;
    }

    .badge {
      display: inline-flex;
      align-items: center;
      min-height: 2rem;
      padding: 0.3rem 0.75rem;
      border-radius: 999px;
      background: rgba(31, 26, 23, 0.06);
      color: var(--color-text);
      font-size: 0.88rem;
      font-weight: 600;
    }

    .content-grid {
      display: grid;
      gap: 1.5rem;
      padding: 1.5rem 0 3rem;
    }

    .section-card {
      padding: clamp(1.2rem, 2vw, 1.6rem);
    }

    .section-heading {
      display: flex;
      align-items: end;
      justify-content: space-between;
      gap: 1rem;
      margin-bottom: 1.1rem;
    }

    .section-heading h2 {
      margin: 0;
      font-size: clamp(1.4rem, 2vw, 2rem);
      line-height: 1.1;
    }

    .section-heading p {
      margin: 0;
      color: var(--color-muted-text);
      max-width: 34ch;
    }

    .product-toolbar {
      display: flex;
      flex-wrap: wrap;
      gap: 0.5rem;
      margin-bottom: 1rem;
    }

    .filter-chip {
      min-height: 2.5rem;
      padding: 0.55rem 0.95rem;
      border-radius: 999px;
      border: 1px solid var(--color-border);
      background: transparent;
      color: var(--color-text);
      font: inherit;
      font-weight: 600;
      cursor: pointer;
    }

    .filter-chip[aria-pressed="true"] {
      background: var(--color-text);
      color: #fff;
      border-color: var(--color-text);
    }

    .grid-products,
    .grid-editorial {
      display: grid;
      gap: 1rem;
      grid-template-columns: repeat(3, minmax(0, 1fr));
    }

    .product-card,
    .editorial-card {
      border: 1px solid var(--color-border);
      border-radius: var(--radius-lg);
      background: linear-gradient(180deg, #fff, #fcfaf6);
      overflow: hidden;
      min-width: 0;
    }

    .product-card {
      display: grid;
      grid-template-rows: auto 1fr;
    }

    .product-art {
      aspect-ratio: 4 / 3;
      padding: 1rem;
      display: grid;
      align-content: end;
      color: #fff;
      background: linear-gradient(135deg, #59453a, #b57e56 52%, #f0d4ba);
    }

    .product-art p {
      margin: 0;
      max-width: 12ch;
      font-size: 1.05rem;
      font-weight: 700;
    }

    .product-body,
    .editorial-body {
      display: grid;
      gap: 0.75rem;
      padding: 1rem;
    }

    .product-body h3,
    .editorial-body h3 {
      margin: 0;
      font-size: 1.1rem;
    }

    .product-body p,
    .editorial-body p {
      margin: 0;
      color: var(--color-muted-text);
    }

    .product-footer {
      display: flex;
      align-items: center;
      justify-content: space-between;
      gap: 1rem;
      margin-top: 0.25rem;
    }

    .price {
      font-weight: 700;
      font-size: 1.05rem;
      white-space: nowrap;
    }

    .mini-button {
      min-height: 2.5rem;
      padding: 0.55rem 0.9rem;
      border: 1px solid var(--color-border);
      border-radius: 999px;
      background: transparent;
      color: var(--color-text);
      font: inherit;
      font-weight: 600;
      cursor: pointer;
    }

    .mini-button[aria-pressed="true"] {
      background: #f3e0cc;
      border-color: #c9986d;
    }

    .deal-banner {
      display: grid;
      grid-template-columns: 1fr auto;
      gap: 1rem;
      align-items: center;
      padding: 1.25rem;
      border-radius: var(--radius-xl);
      background: linear-gradient(135deg, #221914, #5a3525 48%, #8a5035);
      color: #fff;
    }

    .deal-banner h2,
    .deal-banner p {
      margin: 0;
    }

    .deal-banner p {
      color: rgba(255, 255, 255, 0.84);
      max-width: 48ch;
    }

    .deal-timer {
      display: flex;
      gap: 0.75rem;
      flex-wrap: wrap;
      justify-content: end;
    }

    .timer-unit {
      min-width: 5rem;
      padding: 0.75rem 0.9rem;
      border-radius: 1rem;
      background: rgba(255, 255, 255, 0.12);
      text-align: center;
    }

    .timer-unit strong {
      display: block;
      font-size: 1.35rem;
      line-height: 1;
    }

    .timer-unit span {
      font-size: 0.8rem;
      color: rgba(255, 255, 255, 0.76);
    }

    .editorial-card figure {
      margin: 0;
    }

    .editorial-image {
      aspect-ratio: 16 / 10;
      background:
        radial-gradient(circle at 75% 20%, rgba(255,255,255,0.24), transparent 24%),
        linear-gradient(135deg, #e5d0bd 0%, #b7825b 50%, #463227 100%);
    }

    .editorial-meta {
      display: flex;
      gap: 0.5rem;
      flex-wrap: wrap;
      color: var(--color-muted-text);
      font-size: 0.9rem;
    }

    .editorial-meta time::before {
      content: "•";
      margin-right: 0.5rem;
    }

    .newsletter {
      display: grid;
      gap: 1rem;
      grid-template-columns: 1.2fr 0.8fr;
      align-items: center;
    }

    .newsletter form {
      display: flex;
      flex-wrap: wrap;
      gap: 0.75rem;
    }

    .newsletter label {
      width: 100%;
      font-weight: 600;
    }

    .newsletter input {
      flex: 1 1 16rem;
      min-width: 0;
      min-height: 2.875rem;
      padding: 0.75rem 1rem;
      border: 1px solid var(--color-border);
      border-radius: 999px;
      background: #fff;
      color: var(--color-text);
      font: inherit;
    }

    .newsletter input::placeholder {
      color: #81756a;
    }

    .status {
      min-height: 1.25rem;
      color: var(--color-success);
      font-weight: 600;
    }

    .site-footer {
      padding: 0 0 2rem;
      color: var(--color-muted-text);
    }

    .footer-card {
      display: flex;
      flex-wrap: wrap;
      justify-content: space-between;
      gap: 1rem;
      padding: 1rem 1.25rem;
      border-top: 1px solid var(--color-border);
    }

    .footer-card p {
      margin: 0;
    }

    .footer-links {
      display: flex;
      gap: 1rem;
      flex-wrap: wrap;
    }

    .sr-only {
      position: absolute;
      width: 1px;
      height: 1px;
      padding: 0;
      margin: -1px;
      overflow: hidden;
      clip: rect(0, 0, 0, 0);
      white-space: nowrap;
      border: 0;
    }

    @media (max-width: 64rem) {
      .hero,
      .newsletter,
      .deal-banner {
        grid-template-columns: 1fr;
      }

      .grid-products,
      .grid-editorial {
        grid-template-columns: repeat(2, minmax(0, 1fr));
      }

      .deal-timer {
        justify-content: start;
      }
    }

    @media (max-width: 42rem) {
      .page-shell {
        width: min(100% - 1rem, var(--content-width));
      }

      .header-bar {
        border-radius: 1.5rem;
        align-items: start;
        flex-direction: column;
      }

      .site-nav ul,
      .hero-actions,
      .product-toolbar,
      .footer-links {
        width: 100%;
      }

      .site-nav ul {
        flex-direction: column;
      }

      .site-nav a {
        width: 100%;
        justify-content: center;
      }

      .grid-products,
      .grid-editorial {
        grid-template-columns: 1fr;
      }

      .section-heading {
        align-items: start;
        flex-direction: column;
      }

      .hero-copy {
        padding: 1.25rem;
      }

      h1 {
        max-width: 10ch;
      }
    }

    @media (forced-colors: active) {
      :root {
        --color-bg: Canvas;
        --color-surface: Canvas;
        --color-surface-alt: Canvas;
        --color-text: CanvasText;
        --color-muted-text: CanvasText;
        --color-link: LinkText;
        --color-border: ButtonBorder;
        --color-focus: Highlight;
      }

      body {
        background: Canvas;
      }

      .header-bar,
      .hero-copy,
      .hero-panel,
      .section-card,
      .product-card,
      .editorial-card,
      .deal-banner {
        box-shadow: none;
        border-color: ButtonBorder;
      }

      .button,
      .button.secondary,
      .filter-chip,
      .mini-button,
      .newsletter input {
        forced-color-adjust: auto;
        border-color: ButtonBorder;
        background: ButtonFace;
        color: ButtonText;
      }

      .filter-chip[aria-pressed="true"],
      .mini-button[aria-pressed="true"] {
        background: Highlight;
        color: HighlightText;
      }

      .badge,
      .brand-mark,
      .product-art,
      .feature-visual,
      .editorial-image {
        forced-color-adjust: none;
        background: Canvas;
        color: CanvasText;
        border: 1px solid ButtonBorder;
      }

      .feature-visual::before {
        border-color: ButtonBorder;
      }
    }
  </style>
</head>
<body>
  <a class="skip-link" href="#maincontent">Skip to main content</a>

  <header class="site-header page-shell">
    <div class="header-bar">
      <a class="brand" href="#maincontent">
        <span class="brand-mark" aria-hidden="true">N</span>
        <span>Northstar Retail</span>
      </a>

      <nav class="site-nav" aria-label="Primary">
        <ul>
          <li><a href="#featured-products">Featured</a></li>
          <li><a href="#deals">Deals</a></li>
          <li><a href="#editorial">Stories</a></li>
          <li><a href="#newsletter">Join list</a></li>
        </ul>
      </nav>
    </div>
  </header>

  <main id="maincontent" class="page-shell" tabindex="-1">
    <section class="hero" aria-labelledby="hero-title">
      <div class="hero-copy">
        <p class="eyebrow">New season collection</p>
        <h1 id="hero-title">Elevated essentials for every room</h1>
        <p>Discover curated furniture, home goods, and gifting ideas built around warm materials, clean lines, and everyday comfort.</p>
        <div class="hero-actions">
          <a class="button" href="#featured-products">Shop featured products</a>
          <a class="button secondary" href="#editorial">Read the latest edit</a>
        </div>
        <dl class="hero-meta" aria-label="Store highlights">
          <div>
            <dt>Ships free</dt>
            <dd>On orders over $75</dd>
          </div>
          <div>
            <dt>Returns</dt>
            <dd>30-day easy policy</dd>
          </div>
          <div>
            <dt>Members</dt>
            <dd>Early access to drops</dd>
          </div>
        </dl>
      </div>

      <aside class="hero-panel" aria-label="Featured spotlight">
        <div class="feature-spot">
          <div class="feature-visual" aria-hidden="true">
            <strong>Signature lounge chair</strong>
            <p>Soft boucle, walnut base, limited spring run.</p>
          </div>
          <div class="badge-row" aria-label="Top highlights">
            <span class="badge">Bestseller</span>
