       flex-wrap: wrap;
       justify-content: end;
     }

     .timer-unit {
       min-width: 5rem;
       padding: 0.75rem 0.9rem;
       border-radius: 1rem;
       background: rgba(255, 255, 255, 0.12);
       text-align: center;
     }

     .timer-unit strong {
       display: block;
       font-size: 1.35rem;
       line-height: 1;
     }

     .timer-unit span {
       font-size: 0.8rem;
       color: rgba(255, 255, 255, 0.76);
     }

     .editorial-card figure {
       margin: 0;
     }

     .editorial-image {
       aspect-ratio: 16 / 10;
       background:
         radial-gradient(circle at 75% 20%, rgba(255,255,255,0.24), transparent 24%),
         linear-gradient(135deg, #e5d0bd 0%, #b7825b 50%, #463227 100%);
     }

     .editorial-meta {
       display: flex;
       gap: 0.5rem;
       flex-wrap: wrap;
       color: var(--color-muted-text);
       font-size: 0.9rem;
     }

     .editorial-meta time::before {
       content: "•";
       margin-right: 0.5rem;
     }

     .newsletter {
       display: grid;
       gap: 1rem;
       grid-template-columns: 1.2fr 0.8fr;
       align-items: center;
     }

     .newsletter form {
       display: flex;
       flex-wrap: wrap;
       gap: 0.75rem;
     }

     .newsletter label {
       width: 100%;
       font-weight: 600;
     }

     .newsletter input {
       flex: 1 1 16rem;
       min-width: 0;
       min-height: 2.875rem;
       padding: 0.75rem 1rem;
       border: 1px solid var(--color-border);
       border-radius: 999px;
       background: #fff;
       color: var(--color-text);
       font: inherit;
     }

     .newsletter input::placeholder {
       color: #81756a;
     }

     .status {
       min-height: 1.25rem;
       color: var(--color-success);
       font-weight: 600;
     }

     .site-footer {
       padding: 0 0 2rem;
       color: var(--color-muted-text);
     }

     .footer-card {
       display: flex;
       flex-wrap: wrap;
       justify-content: space-between;
       gap: 1rem;
       padding: 1rem 1.25rem;
       border-top: 1px solid var(--color-border);
     }

     .footer-card p {
       margin: 0;
     }

     .footer-links {
       display: flex;
       gap: 1rem;
       flex-wrap: wrap;
     }

     .sr-only {
       position: absolute;
       width: 1px;
       height: 1px;
       padding: 0;
       margin: -1px;
       overflow: hidden;
       clip: rect(0, 0, 0, 0);
       white-space: nowrap;
       border: 0;
     }

     @media (max-width: 64rem) {
       .hero,
       .newsletter,
       .deal-banner {
         grid-template-columns: 1fr;
       }

       .grid-products,
       .grid-editorial {
         grid-template-columns: repeat(2, minmax(0, 1fr));
       }

       .deal-timer {
         justify-content: start;
       }
     }

     @media (max-width: 42rem) {
       .page-shell {
         width: min(100% - 1rem, var(--content-width));
       }

       .header-bar {
         border-radius: 1.5rem;
         align-items: start;
         flex-direction: column;
       }

       .site-nav ul,
       .hero-actions,
       .product-toolbar,
       .footer-links {
         width: 100%;
       }

       .site-nav ul {
         flex-direction: column;
       }

       .site-nav a {
         width: 100%;
         justify-content: center;
       }

       .grid-products,
       .grid-editorial {
         grid-template-columns: 1fr;
       }

       .section-heading {
         align-items: start;
         flex-direction: column;
       }

       .hero-copy {
         padding: 1.25rem;
       }

       h1 {
         max-width: 10ch;
       }
     }

     @media (forced-colors: active) {
       :root {
         --color-bg: Canvas;
         --color-surface: Canvas;
         --color-surface-alt: Canvas;
         --color-text: CanvasText;
         --color-muted-text: CanvasText;
         --color-link: LinkText;
         --color-border: ButtonBorder;
         --color-focus: Highlight;
       }

       body {
         background: Canvas;
       }

       .header-bar,
       .hero-copy,
       .hero-panel,
       .section-card,
       .product-card,
       .editorial-card,
       .deal-banner {
         box-shadow: none;
         border-color: ButtonBorder;
       }

       .button,
       .button.secondary,
       .filter-chip,
       .mini-button,
       .newsletter input {
         forced-color-adjust: auto;
         border-color: ButtonBorder;
         background: ButtonFace;
         color: ButtonText;
       }

       .filter-chip[aria-pressed="true"],
       .mini-button[aria-pressed="true"] {
         background: Highlight;
         color: HighlightText;
       }

       .badge,
       .brand-mark,
       .product-art,
       .feature-visual,
       .editorial-image {
         forced-color-adjust: none;
         background: Canvas;
         color: CanvasText;
         border: 1px solid ButtonBorder;
       }

       .feature-visual::before {
         border-color: ButtonBorder;
       }
     }
   </style>
 </head>
 <body>
   <a class="skip-link" href="#maincontent">Skip to main content</a>

   <header class="site-header page-shell">
     <div class="header-bar">
       <a class="brand" href="#maincontent">
         <span class="brand-mark" aria-hidden="true">N</span>
         <span>Northstar Retail</span>
       </a>

       <nav class="site-nav" aria-label="Primary">
         <ul>
           <li><a href="#featured-products">Featured</a></li>
           <li><a href="#deals">Deals</a></li>
           <li><a href="#editorial">Stories</a></li>
           <li><a href="#newsletter">Join list</a></li>
         </ul>
       </nav>
     </div>
   </header>

   <main id="maincontent" class="page-shell" tabindex="-1">
     <section class="hero" aria-labelledby="hero-title">
       <div class="hero-copy">
         <p class="eyebrow">New season collection</p>
         <h1 id="hero-title">Elevated essentials for every room</h1>
         <p>Discover curated furniture, home goods, and gifting ideas built around warm materials, clean lines, and everyday comfort.</p>
         <div class="hero-actions">
           <a class="button" href="#featured-products">Shop featured products</a>
           <a class="button secondary" href="#editorial">Read the latest edit</a>
         </div>
         <dl class="hero-meta" aria-label="Store highlights">
           <div>
             <dt>Ships free</dt>
             <dd>On orders over $75</dd>
           </div>
           <div>
             <dt>Returns</dt>
             <dd>30-day easy policy</dd>
           </div>
           <div>
             <dt>Members</dt>
             <dd>Early access to drops</dd>
           </div>
         </dl>
       </div>

       <aside class="hero-panel" aria-label="Featured spotlight">
         <div class="feature-spot">
           <div class="feature-visual" aria-hidden="true">
             <strong>Signature lounge chair</strong>
             <p>Soft boucle, walnut base, limited spring run.</p>
           </div>
           <div class="badge-row" aria-label="Top highlights">
             <span class="badge">Bestseller</span>
             <span class="badge">Designer pick</span>
             <span class="badge">Low stock</span>
           </div>
         </div>
         <p>Thoughtful materials and calm color palettes make it easy to build a home that feels collected, not cluttered.</p>
       </aside>
     </section>

     <div class="content-grid">
       <section id="featured-products" class="section-card" aria-labelledby="featured-title">
         <div class="section-heading">
           <div>
             <h2 id="featured-title">Featured products</h2>
             <p>Fresh arrivals selected for style, value, and everyday use.</p>
           </div>
           <div class="product-toolbar" aria-label="Product filters">
             <button class="filter-chip" type="button" data-filter="all" aria-pressed="true">All</button>
             <button class="filter-chip" type="button" data-filter="living" aria-pressed="false">Living</button>
             <button class="filter-chip" type="button" data-filter="kitchen" aria-pressed="false">Kitchen</button>
             <button class="filter-chip" type="button" data-filter="decor" aria-pressed="false">Decor</button>
           </div>
         </div>

         <div class="grid-products" id="product-grid" aria-live="polite"></div>
       </section>

       <section id="deals" class="section-card" aria-labelledby="deals-title">
         <div class="section-heading">
           <div>
             <h2 id="deals-title">Deal of the day</h2>
             <p>Limited-time savings on a few customer favorites.</p>
           </div>
         </div>
         <article class="deal-banner" aria-labelledby="deal-heading">
           <div>
             <h3 id="deal-heading">Save 25% on the Atelier storage collection</h3>
             <p>Clean silhouettes, adjustable shelving, and soft-close hardware for organized spaces that still feel warm.</p>
           </div>
           <div class="deal-timer" aria-label="Deal time remaining">
             <div class="timer-unit"><strong id="hours">12</strong><span>hours</span></div>
             <div class="timer-unit"><strong id="minutes">24</strong><span>minutes</span></div>
             <div class="timer-unit"><strong id="seconds">18</strong><span>seconds</span></div>
           </div>
         </article>
       </section>

       <section id="editorial" class="section-card" aria-labelledby="editorial-title">
         <div class="section-heading">
           <div>
             <h2 id="editorial-title">Editorial content</h2>
             <p>Design guidance, seasonal edits, and home inspiration.</p>
           </div>
         </div>

         <div class="grid-editorial">
           <article class="editorial-card" id="texture-article">
             <figure>
               <div class="editorial-image" aria-hidden="true"></div>
             </figure>
             <div class="editorial-body">
               <div class="editorial-meta">
                 <span>Style guide</span>
                 <time datetime="2026-05-05">May 5, 2026</time>
               </div>
               <h3>How to layer texture without making a room feel busy</h3>
               <p>Use one anchor material, one accent finish, and a pair of tactile pieces to create balance.</p>
               <a href="#texture-article">Read the article</a>
             </div>
           </article>

           <article class="editorial-card" id="layout-article">
             <figure>
               <div class="editorial-image" aria-hidden="true"></div>
             </figure>
             <div class="editorial-body">
               <div class="editorial-meta">
                 <span>Room story</span>
                 <time datetime="2026-04-28">April 28, 2026</time>
               </div>
               <h3>A compact apartment gets a softer, smarter layout</h3>
               <p>Small footprint? Focus on modular pieces, hidden storage, and a consistent wood tone.</p>
               <a href="#layout-article">See the layout</a>
             </div>
           </article>

           <article class="editorial-card" id="gifts-article">
             <figure>
               <div class="editorial-image" aria-hidden="true"></div>
             </figure>
             <div class="editorial-body">
               <div class="editorial-meta">
                 <span>Gift edit</span>
                 <time datetime="2026-04-20">April 20, 2026</time>
               </div>
               <h3>Easy gifts for hosts, new homeowners, and new grads</h3>
               <p>From candle sets to serving ware, these picks are polished and easy to wrap.</p>
               <a href="#gifts-article">Browse gifts</a>
             </div>
           </article>
         </div>
       </section>

       <section id="newsletter" class="section-card newsletter" aria-labelledby="newsletter-title">
         <div>
           <h2 id="newsletter-title">Join the mailing list</h2>
           <p>Get product drops, styling notes, and private sale alerts in your inbox.</p>
         </div>
         <form id="signup-form">
           <label for="email">Email address</label>
           <input id="email" name="email" type="email" autocomplete="email" placeholder="you@example.com" required>
           <button class="button" type="submit">Subscribe</button>
           <p class="status" id="signup-status" role="status" aria-live="polite"></p>
         </form>
       </section>
     </div>
   </main>

   <footer class="site-footer page-shell">
     <div class="footer-card">
       <p>&copy; 2026 Northstar Retail. Designed for modern living.</p>
       <div class="footer-links" aria-label="Footer links">
         <a href="#featured-products">Shipping</a>
         <a href="#deals">Returns</a>
         <a href="#newsletter">Contact</a>
       </div>
     </div>
   </footer>

   <script>
     const products = [
       {
         name: 'Haven Modular Sofa',
         category: 'living',
         description: 'Deep seating, stain-resistant fabric, and removable cushions for easy care.',
         price: '$1,240',
         accent: 'Best for cozy living rooms',
       },
       {
         name: 'Cedar Stoneware Set',
         category: 'kitchen',
         description: 'A 16-piece set with matte glaze and a hand-finished edge.',
         price: '$88',
         accent: 'Dinnerware with quiet texture',
       },
       {
         name: 'Luma Table Lamp',
         category: 'decor',
         description: 'Soft glow, compact footprint, and a linen shade for bedside warmth.',
         price: '$124',
         accent: 'Small-space lighting',
       },
       {
         name: 'Aria Side Table',
         category: 'living',
         description: 'Oak veneer and a sculpted silhouette with a hidden shelf for remotes.',
         price: '$165',
         accent: 'Adds function beside a sofa',
       },
       {
         name: 'Market Pantry Canisters',
         category: 'kitchen',
         description: 'A stackable trio that keeps staples visible and counters tidy.',
         price: '$52',
         accent: 'Storage that looks polished',
       },
       {
         name: 'Terrace Throw Pillow',
         category: 'decor',
         description: 'Hand-loomed cotton with a muted stripe that works across seasons.',
         price: '$38',
         accent: 'An easy color refresh',
       }
     ];

     const productGrid = document.getElementById('product-grid');
     const filterButtons = Array.from(document.querySelectorAll('.filter-chip'));
     let activeFilter = 'all';
     const savedState = new Set();

     function productCardTemplate(product) {
       const saved = savedState.has(product.name);
       return `
         <article class="product-card" data-category="${product.category}">
           <div class="product-art" aria-hidden="true">
             <p>${product.accent}</p>
           </div>
           <div class="product-body">
             <span class="badge">${product.category}</span>
             <h3>${product.name}</h3>
             <p>${product.description}</p>
             <div class="product-footer">
               <span class="price">${product.price}</span>
               <button class="mini-button" type="button" data-save="${product.name}" aria-pressed="${saved}">
                 ${saved ? 'Saved' : 'Save'}
               </button>
             </div>
           </div>
         </article>
       `;
     }

     function renderProducts() {
       const visible = products.filter((product) => activeFilter === 'all' || product.category === activeFilter);
       productGrid.innerHTML = visible.map(productCardTemplate).join('');
     }

     productGrid.addEventListener('click', (event) => {
       const button = event.target.closest('[data-save]');
       if (!button) {
         return;
       }

       const name = button.getAttribute('data-save');
       if (savedState.has(name)) {
         savedState.delete(name);
       } else {
         savedState.add(name);
       }

       const isSaved = savedState.has(name);
       button.setAttribute('aria-pressed', String(isSaved));
       button.textContent = isSaved ? 'Saved' : 'Save';
     });

     filterButtons.forEach((button) => {
       button.addEventListener('click', () => {
         activeFilter = button.getAttribute('data-filter');
         filterButtons.forEach((control) => control.setAttribute('aria-pressed', String(control === button)));
         renderProducts();
       });
     });

     renderProducts();

     const countdown = {
       hours: 12,
       minutes: 24,
       seconds: 18
     };

     function updateCountdown() {
       countdown.seconds -= 1;
       if (countdown.seconds < 0) {
         countdown.seconds = 59;
         countdown.minutes -= 1;
       }
       if (countdown.minutes < 0) {
         countdown.minutes = 59;
         countdown.hours = Math.max(0, countdown.hours - 1);
       }

       document.getElementById('hours').textContent = String(countdown.hours).padStart(2, '0');
       document.getElementById('minutes').textContent = String(countdown.minutes).padStart(2, '0');
       document.getElementById('seconds').textContent = String(countdown.seconds).padStart(2, '0');
     }

     updateCountdown();
     setInterval(updateCountdown, 1000);

     const form = document.getElementById('signup-form');
     const status = document.getElementById('signup-status');

     form.addEventListener('submit', (event) => {
       event.preventDefault();
       const email = document.getElementById('email');
       status.textContent = email.value
         ? `Thanks. ${email.value} will get the next drop.`
         : 'Enter an email address to subscribe.';
       if (email.value) {
         form.reset();
       }
     });
   </script>
 </body>
 </html>

')
